select ce1_0.id,(select oe1_0.id from orders oe1_0 join customers c1_0 on c1_0.id=oe1_0.customer_id where c1_0.id=ce1_0.id order by oe1_0.status desc,1 limit ?) from customers ce1_0 where ce1_0.id<=? and (select oe2_0.id from orders oe2_0 join customers c2_0 on c2_0.id=oe2_0.customer_id where c2_0.id=ce1_0.id order by oe2_0.status desc,1 limit ?)>=? order by 2 desc
